$json$[{"id":"math-11-trig-q1","prompt":"Tập giá trị của hàm số y = sin x là?","difficulty":"EASY","options":[{"id":"a","text":"[-1; 1]"},{"id":"b","text":"[0; 1]"},{"id":"c","text":"R"}],"correctOptionId":"a","explanation":"Giá trị sin x luôn nằm trong khoảng từ -1 đến 1."},{"id":"math-11-seq-q1","prompt":"Công thức số hạng tổng quát của cấp số cộng u_n là?","difficulty":"EASY","options":[{"id":"a","text":"u_n = u_1 + (n-1)d"},{"id":"b","text":"u_n = u_1 * d^(n-1)"},{"id":"c","text":"u_n = u_1 + nd"}],"correctOptionId":"a","explanation":"Cấp số cộng tăng theo công sai d nhân với (n-1)."}]$json$::jsonb, $json$[]$json$::jsonb)
