insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 11, 'intro-2026.1', 'math-11-trig', 1, 'LESSON', 'Hàm số lượng giác & Phương trình lượng giác', 'Toán 11: Hàm số, Dãy số, Giới hạn và Hình học không gian', 'Bộ bài học Lớp 11 do AI Mentor biên soạn theo chương trình GDPT 2018.',
$json$["Hàm số sin, cos, tan có tính tuần hoàn. Phương trình sin x = sin a có nghiệm x = a + k2π hoặc x = π - a + k2π."]$json$::jsonb,
$json$["Giải sin x = 1/2 => x = π/6 + k2π hoặc x = 5π/6 + k2π (k ∈ Z)."]$json$::jsonb,
$json$[{"id":"math-11-trig-q1","prompt":"Tập giá trị của hàm số y = sin x là?","difficulty":"EASY","options":[{"id":"a","text":"[-1; 1]"},{"id":"b","text":"[0; 1]"},{"id":"c","text":"R"}],"correctOptionId":"a","explanation":"Giá trị sin x luôn nằm trong đoạn [-1; 1]."},{"id":"math-11-trig-q2","prompt":"Phương trình sin x = 0 có nghiệm tổng quát là?","difficulty":"MEDIUM","options":[{"id":"a","text":"x = kπ"},{"id":"b","text":"x = k2π"},{"id":"c","text":"x = π/2 + kπ"}],"correctOptionId":"a","explanation":"sin x = 0 tại các điểm x = 0, π, 2π,... tức là kπ với k ∈ Z."},{"id":"math-11-trig-q3","prompt":"Chu kỳ tuần hoàn của hàm số y = tan x là?","difficulty":"APPLIED","options":[{"id":"a","text":"2π"},{"id":"b","text":"π"},{"id":"c","text":"π/2"}],"correctOptionId":"b","explanation":"Hàm tan x lặp lại giá trị sau mỗi khoảng π."}]$json$::jsonb, $json$["math-11-trig"]$json$::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;

insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 11, 'intro-2026.1', 'math-11-sequences', 2, 'LESSON', 'Dãy số, Cấp số cộng & Cấp số nhân', 'Toán 11: Hàm số, Dãy số, Giới hạn và Hình học không gian', 'Bộ bài học Lớp 11 do AI Mentor biên soạn theo chương trình GDPT 2018.',
$json$["Cấp số cộng có u_(n+1) = u_n + d. Cấp số nhân có u_(n+1) = u_n * q."]$json$::jsonb,
$json$["Dãy 2, 5, 8, 11 là cấp số cộng có u_1 = 2, d = 3. Dãy 3, 6, 12, 24 là cấp số nhân có q = 2."]$json$::jsonb,
$json$[{"id":"math-11-seq-q1","prompt":"Công thức số hạng tổng quát của cấp số cộng u_n là?","difficulty":"EASY","options":[{"id":"a","text":"u_n = u_1 + (n-1)d"},{"id":"b","text":"u_n = u_1 * d^(n-1)"},{"id":"c","text":"u_n = u_1 + nd"}],"correctOptionId":"a","explanation":"Mỗi bước cộng thêm d, sau n-1 bước thu được u_n."},{"id":"math-11-seq-q2","prompt":"Cho cấp số nhân có u_1 = 3, công bội q = 2. Số hạng u_4 bằng bao nhiêu?","difficulty":"MEDIUM","options":[{"id":"a","text":"24"},{"id":"b","text":"18"},{"id":"c","text":"12"}],"correctOptionId":"a","explanation":"u_4 = u_1 * q^3 = 3 * 2^3 = 24."},{"id":"math-11-seq-q3","prompt":"Tổng n số hạng đầu của cấp số cộng u_1 = 1, d = 2 (tổng các số lẻ) là?","difficulty":"APPLIED","options":[{"id":"a","text":"n^2"},{"id":"b","text":"2n"},{"id":"c","text":"n(n+1)"}],"correctOptionId":"a","explanation":"S_n = n/2 * (2*1 + (n-1)*2) = n^2."}]$json$::jsonb, $json$["math-11-sequences"]$json$::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;

insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 11, 'intro-2026.1', 'math-11-limits', 3, 'LESSON', 'Giới hạn của dãy số & Hàm số', 'Toán 11: Hàm số, Dãy số, Giới hạn và Hình học không gian', 'Bộ bài học Lớp 11 do AI Mentor biên soạn theo chương trình GDPT 2018.',
$json$["lim (1/n) = 0 khi n -> ∞. Nếu |q| < 1 thì lim q^n = 0."]$json$::jsonb,
$json$["lim (2n+1)/(n+3) = 2 khi n -> ∞."]$json$::jsonb,
$json$[{"id":"math-11-lim-q1","prompt":"Giá trị lim (1/n) khi n tiến ra vô cùng là?","difficulty":"EASY","options":[{"id":"a","text":"0"},{"id":"b","text":"1"},{"id":"c","text":"Vô cực"}],"correctOptionId":"a","explanation":"Khi mẫu số tiến ra vô cực thì phân số tiến về 0."},{"id":"math-11-lim-q2","prompt":"lim (3n^2 + 2)/(n^2 - 1) khi n -> ∞ bằng?","difficulty":"MEDIUM","options":[{"id":"a","text":"3"},{"id":"b","text":"2"},{"id":"c","text":"1"}],"correctOptionId":"a","explanation":"Chia cả tử và mẫu cho n^2 ta thu được 3/1 = 3."},{"id":"math-11-lim-q3","prompt":"Hàm số f(x) liên tục tại x_0 khi nào?","difficulty":"APPLIED","options":[{"id":"a","text":"lim x->x_0 f(x) = f(x_0)"},{"id":"b","text":"f(x_0) = 0"},{"id":"c","text":"lim x->x_0 f(x) = 0"}],"correctOptionId":"a","explanation":"Định nghĩa hàm số liên tục tại 1 điểm."}]$json$::jsonb, $json$["math-11-limits"]$json$::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;

insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 11, 'intro-2026.1', 'math-11-derivatives', 4, 'LESSON', 'Đạo hàm & Ý nghĩa hình học', 'Toán 11: Hàm số, Dãy số, Giới hạn và Hình học không gian', 'Bộ bài học Lớp 11 do AI Mentor biên soạn theo chương trình GDPT 2018.',
$json$["Đạo hàm f'(x_0) là hệ số góc của tiếp tuyến của đồ thị hàm số tại x_0. (x^n)' = n * x^(n-1)."]$json$::jsonb,
$json$["Đạo hàm của f(x) = x^3 - 2x là f'(x) = 3x^2 - 2."]$json$::jsonb,
$json$[{"id":"math-11-der-q1","prompt":"Đạo hàm của hàm số f(x) = x^2 tại x = 3 là?","difficulty":"EASY","options":[{"id":"a","text":"6"},{"id":"b","text":"9"},{"id":"c","text":"3"}],"correctOptionId":"a","explanation":"f'(x) = 2x => f'(3) = 2 * 3 = 6."},{"id":"math-11-der-q2","prompt":"Đạo hàm của sin x là?","difficulty":"MEDIUM","options":[{"id":"a","text":"cos x"},{"id":"b","text":"-cos x"},{"id":"c","text":"-sin x"}],"correctOptionId":"a","explanation":"(sin x)' = cos x."},{"id":"math-11-der-q3","prompt":"Ý nghĩa hình học của đạo hàm f'(x_0) là?","difficulty":"APPLIED","options":[{"id":"a","text":"Hệ số góc của tiếp tuyến tại x_0"},{"id":"b","text":"Khoảng cách tới gốc tọa độ"},{"id":"c","text":"Diện tích hình phẳng"}],"correctOptionId":"a","explanation":"f'(x_0) chính là k trong phương trình tiếp tuyến y = k(x - x_0) + y_0."}]$json$::jsonb, $json$["math-11-derivatives"]$json$::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;

