$json$[{"id":"math-11-geo-q1","prompt":"Hai đường thẳng không cùng thuộc một mặt phẳng gọi là?","difficulty":"EASY","options":[{"id":"a","text":"Chéo nhau"},{"id":"b","text":"Song song"},{"id":"c","text":"Cắt nhau"}],"correctOptionId":"a","explanation":"Định nghĩa hai đường thẳng chéo nhau trong không gian 3D."},{"id":"math-11-geo-q2","prompt":"Nếu d ⊥ a và d ⊥ b (a, b cắt nhau nằm trong (P)) thì?","difficulty":"MEDIUM","options":[{"id":"a","text":"d ⊥ (P)"},{"id":"b","text":"d // (P)"},{"id":"c","text":"d ⊂ (P)"}],"correctOptionId":"a","explanation":"Điều kiện đường thẳng vuông góc với mặt phẳng."},{"id":"math-11-geo-q3","prompt":"Góc giữa hai đường thẳng vuông góc nhau bằng?","difficulty":"APPLIED","options":[{"id":"a","text":"90°"},{"id":"b","text":"180°"},{"id":"c","text":"0°"}],"correctOptionId":"a","explanation":"Hai đường thẳng vuông góc có góc bằng 90 độ."}]$json$::jsonb, $json$["math-11-geometry3d"]$json$::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;

