$json$[{"id":"phy-11-osc-q1","prompt":"Phương trình dao động điều hòa x = A cos(ωt + φ), A là?","difficulty":"EASY","options":[{"id":"a","text":"Biên độ dao động"},{"id":"b","text":"Pha ban đầu"},{"id":"c","text":"Tần số góc"}],"correctOptionId":"a","explanation":"A là ly độ cực đại, gọi là biên độ dao động."}]$json$::jsonb, $json$[]$json$::jsonb)
