insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('physics', 11, 'intro-2026.1', 'physics-11-oscillation', 1, 'LESSON', 'Dao động điều hòa & Phương trình dao động', 'Vật lý 11: Dao động, Sóng và Điện trường', 'Bộ bài học Lớp 11 do AI Mentor biên soạn.',
$json$["Dao động điều hòa có ly độ x = A cos(ωt + φ). Vận tốc v = x' = -ωA sin(ωt + φ), gia tốc a = v' = -ω^2 x."]$json$::jsonb,
$json$["Gia tốc luôn ngược dấu và tỉ lệ với ly độ: a = -ω^2 x."]$json$::jsonb,
$json$[{"id":"phy-11-osc-q1","prompt":"Phương trình dao động x = A cos(ωt + φ), A đại diện cho?","difficulty":"EASY","options":[{"id":"a","text":"Biên độ dao động"},{"id":"b","text":"Tần số góc"},{"id":"c","text":"Pha ban đầu"}],"correctOptionId":"a","explanation":"A là độ dịch chuyển cực đại so với vị trí cân bằng."},{"id":"phy-11-osc-q2","prompt":"Gia tốc trong dao động điều hòa biến thiên như thế nào so với ly độ?","difficulty":"MEDIUM","options":[{"id":"a","text":"Ngược pha với ly độ"},{"id":"b","text":"Cùng pha với ly độ"},{"id":"c","text":"Vuông pha với ly độ"}],"correctOptionId":"a","explanation":"Do a = -ω^2 x nên gia tốc ngược pha với ly độ."},{"id":"phy-11-osc-q3","prompt":"Tại vị trí cân bằng, vận tốc của vật dao động điều hòa có độ lớn?","difficulty":"APPLIED","options":[{"id":"a","text":"Cực đại v_max = ωA"},{"id":"b","text":"Bằng 0"},{"id":"c","text":"Cực tiểu bằng -ωA"}],"correctOptionId":"a","explanation":"Tại VCB ly độ x = 0, vận tốc đạt giá trị cực đại v_max = ωA."}]$json$::jsonb, $json$["physics-11-oscillation"]$json$::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;

insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('physics', 11, 'intro-2026.1', 'physics-11-pendulum', 2, 'LESSON', 'Con lắc đơn & Con lắc lò xo', 'Vật lý 11: Dao động, Sóng và Điện trường', 'Bộ bài học Lớp 11 do AI Mentor biên soạn.',
$json$["Con lắc lò xo có chu kỳ T = 2π √(m/k). Con lắc đơn có chu kỳ T = 2π √(l/g)."]$json$::jsonb,
$json$["Tăng khối lượng m của con lắc lò xo lên 4 lần thì chu kỳ T tăng gấp 2 lần."]$json$::jsonb,
$json$[{"id":"phy-11-pen-q1","prompt":"Chu kỳ dao động của con lắc lò xo phụ thuộc vào?","difficulty":"EASY","options":[{"id":"a","text":"Khối lượng m và độ cứng k"},{"id":"b","text":"Chiều dài dây treo"},{"id":"c","text":"Gia tốc trọng trường g"}],"correctOptionId":"a","explanation":"T = 2π √(m/k) nên phụ thuộc m và k."},{"id":"phy-11-pen-q2","prompt":"Nếu chiều dài con lắc đơn tăng 4 lần thì chu kỳ dao động nhỏ sẽ?","difficulty":"MEDIUM","options":[{"id":"a","text":"Tăng 2 lần"},{"id":"b","text":"Tăng 4 lần"},{"id":"c","text":"Giảm 2 lần"}],"correctOptionId":"a","explanation":"T tỉ lệ thuận với √l; √4 = 2."},{"id":"phy-11-pen-q3","prompt":"Động năng và thế năng của con lắc dao động biến thiên với chu kỳ bằng?","difficulty":"APPLIED","options":[{"id":"a","text":"T/2"},{"id":"b","text":"T"},{"id":"c","text":"2T"}],"correctOptionId":"a","explanation":"Năng lượng biến thiên với tần số gấp đôi, chu kỳ bằng T/2."}]$json$::jsonb, $json$["physics-11-pendulum"]$json$::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;


