insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('chemistry', 11, 'intro-2026.1', 'chem-11-equilibrium', 1, 'LESSON', 'Cân bằng hóa học & Hằng số Kc', 'Hóa học 11: Cân bằng hóa học & Hóa hữu cơ', 'Bộ bài học Lớp 11 do AI Mentor biên soạn.',
$json$["Cân bằng hóa học xảy ra với phản ứng thuận nghịch. Hằng số Kc = [C]^c [D]^d / ([A]^a [B]^b). Nguyên lý Le Chatelier: Hệ tự chuyển dịch chống lại sự thay đổi tác động."]$json$::jsonb,
$json$["Tăng áp suất làm cân bằng chuyển dịch theo chiều giảm số phân tử khí."]$json$::jsonb,
$json$[{"id":"chem-11-eq-q1","prompt":"Trạng thái cân bằng hóa học là trạng thái?","difficulty":"EASY","options":[{"id":"a","text":"Tốc độ phản ứng thuận bằng tốc độ phản ứng nghịch"},{"id":"b","text":"Nồng độ các chất bằng 0"},{"id":"c","text":"Phản ứng dừng hẳn"}],"correctOptionId":"a","explanation":"Cân bằng hóa học là cân bằng động."},{"id":"chem-11-eq-q2","prompt":"Yếu tố nào KHÔNG làm chuyển dịch cân bằng hóa học?","difficulty":"MEDIUM","options":[{"id":"a","text":"Chất xúc tác"},{"id":"b","text":"Nhiệt độ"},{"id":"c","text":"Nồng độ"}],"correctOptionId":"a","explanation":"Chất xúc tác làm tăng tốc độ cả 2 chiều như nhau nên không làm chuyển dịch cân bằng."},{"id":"chem-11-eq-q3","prompt":"Với phản ứng tỏa nhiệt (ΔH < 0), khi tăng nhiệt độ cân bằng sẽ chuyên dịch theo chiều nào?","difficulty":"APPLIED","options":[{"id":"a","text":"Chiều nghịch (chiều thu nhiệt)"},{"id":"b","text":"Chiều thuận"},{"id":"c","text":"Không đổi"}],"correctOptionId":"a","explanation":"Theo nguyên lý Le Chatelier, tăng nhiệt độ làm chuyển dịch theo chiều thu nhiệt (chiều nghịch)."}]$json$::jsonb, $json$["chem-11-equilibrium"]$json$::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;


